shots.draw_js:
clearScene();setBig(null);setEq(null);
note("监督学习：数据集固定",400,280,"g lg");
note("RL：策略决定数据",880,280,"r lg");
setCap("同样是「梯度上升一步」，这两种设定里<b>走坏一步的后果完全不同</b>。");

clearScene();setEq(null);
setBig("步长就是个超参数","调一调总能调对");
setCap("在监督学习里这是对的。<b>RL 里走坏一步可能再也回不来。</b>");

clearScene();setBig(null);setEq(null);
mdpChain({n:4,y:290,r:28,x:400,gap:160,
  label:function(i){return ["θ","θ′","?","?"][i];},
  cls:function(i){return i<2?"g":"r";},
  arcs:[[0,1,"一步","y",0],[1,2,"","r",0],[2,3,"","r",0]]});
note("数据从这里起都是坏的",640,400,"r");
setCap("一步走坏 ⟹ <b>接下来采到的每一批数据都来自那个坏策略</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"监督学习",sub:"数据固定 · 可以纠回来",state:"on"},
  {label:"强化学习",sub:"数据跟着策略走",state:"dead"},
  {label:"所以要",sub:"保证每步都不变差",state:"on"}]});
note("目标从「快」变成「稳",640,420,"y");
setCap("于是目标变了：不再是「走得快」，而是<b>保证每一步都不把事情弄糟</b>。");

clearScene();setBig(null);setEq(null);
note("步长不是调参问题",640,290,"r lg");
note("是信息可得性问题",640,360,"y lg");
setCap("<b>指名反驳</b>：坏步子毁掉的不只是这一步，<b>是接下来的数据来源</b>。");

clearScene();setBig(null);
setEq("$$\\hat A_t=G_t-b(s_t)$$","top");
note("G_t 还是整条回报",640,300,"r lg");
note("方差还在那里",640,360,"r lg");
setCap("基线砍掉了一部分方差。<b>但 G_t 仍然是蒙特卡洛回报。</b>");

clearScene();setEq(null);
setBig("用 critic 只是图省事","不用等回合结束而已");
setCap("省事是真的 —— 但真正买到的是<b>方差</b>，付出的是<b>偏差</b>。");

clearScene();setBig(null);
setEq("$$\\hat A_t=r_t+\\gamma \\hat V(s_{t+1};\\,\\phi)-\\hat V(s_t;\\,\\phi)$$","top");
note("actor：策略 π_θ",400,320,"g lg");
note("critic：值函数 V̂_φ",880,320,"b lg");
setCap("<b>actor-critic</b>：一个网络演（选动作），一个网络评（估值）。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"蒙特卡洛 G_t",sub:"无偏 · 方差大 · 要等回合",state:"on"},
  {label:"critic 自举",sub:"有偏 · 方差小 · 可在线",state:"on"},
  {label:"判据",sub:"总 MSE",state:"on"}]});
note("和 L3 是同一组取舍",640,420,"y");
setCap("这就是 L3 那组取舍<b>原样搬过来</b>：偏差换方差。");

clearScene();setBig(null);setEq(null);
note("买到：方差 + 在线",400,290,"g lg");
note("付出：偏差",880,290,"r lg");
note("critic 还身兼基线",640,400,"y lg");
setCap("<b>指名反驳</b>：不是图省事，是<b>用偏差换方差</b> —— L3 那组取舍的第二次出场。");

clearScene();setBig(null);setEq(null);
note("n=1：TD(0)",400,280,"b lg");
note("n=T：蒙特卡洛",880,280,"g lg");
note("中间呢",640,400,"y lg");
setCap("上一集给了两个<b>端点</b>。<b>中间是空的吗？</b>");

clearScene();setEq(null);
setBig("n 越大越好","越接近无偏，当然越准");
setCap("n 大确实偏差小 —— <b>但方差跟着一起长</b>。判据还是总 MSE。");

clearScene();setBig(null);
setEq("$$G^{(n)}_t=r_t+\\gamma r_{t+1}+\\cdots+\\gamma^{n-1}r_{t+n-1}+\\gamma^{n}\\hat V(s_{t+n})$$","top");
note("前 n 项是真实奖励",640,310,"g lg");
note("最后一项才自举",640,370,"b lg");
setCap("<b>n 步回报</b>：先用 n 个真实奖励，<b>第 n 步之后</b>才交给 V̂。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3],step:560,vals:[0.9000,0.8100,0.5905,0.3487],
  x:360,y:430,w:560,h:170,max:1,
  label:function(i){return ["n=1","n=2","n=5","n=10"][i];},
  cls:function(i){return i===0?"r":"b";},
  fmt:function(v){return v.toFixed(3);}});
note("γ=0.9 时的 γ^n",640,466,"y");
setCap("自举成分按 <b>γ^n</b> 衰减：γ=0.9 时 n=10 已降到 <b>0.349</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"n 小",sub:"偏差大 · 方差小",state:"on"},
  {label:"n 大",sub:"偏差小 · 方差大",state:"on"},
  {label:"最优 n",sub:"通常在中间",state:"on"}]});
note("端点很少是最优的",640,420,"y");
setCap("<b>指名反驳</b>：n 不是越大越好。<b>两个端点通常都不是最优的。</b>");
